import time

class SimplePID:
    def __init__(self, kp, ki):
        self.kp = kp
        self.ki = ki
        self.integral = 0.0

    def update(self, setpoint, measured, dt):
        e = setpoint - measured
        self.integral = self.integral + e * dt
        return min(1.0, max(0.0, self.kp * e + self.ki * self.integral))

def control_task(pid, plant, setpoint, period, duration):
    measured = 0.0
    overruns = 0
    ticks = 0
    start = time.perf_counter()
    next_tick = start
    last = start
    while time.perf_counter() - start < duration:
        next_tick = next_tick + period
        delay = next_tick - time.perf_counter()
        if delay > 0.0:
            time.sleep(delay)
        else:
            overruns = overruns + 1
        ticks = ticks + 1
        now = time.perf_counter()
        dt = min(3.0 * period, max(0.5 * period, now - last))
        last = now
        measured = plant(measured, pid.update(setpoint, measured, dt), dt)
    return measured, overruns, ticks

def plant(measured, u, dt):
    return measured + (180.0 * u - measured) * (dt / 0.35)

def stalling_plant(measured, u, dt):
    time.sleep(0.003)
    return plant(measured, u, dt)

