class SlewLimiter:
    def __init__(self, rate, value=0.0):
        self.rate = rate
        self.value = value

    def update(self, target, dt):
        step = self.rate * dt
        delta = target - self.value
        if delta > step:
            delta = step
        if delta < -step:
            delta = -step
        self.value = self.value + delta
        return self.value

