class OutputStage:
    def __init__(self, dead=0.15, rate=6.0, low=-1.0, high=1.0):
        self.dead = dead
        self.rate = rate
        self.low = low
        self.high = high
        self.value = 0.0
        self.saturated = False

    def process(self, u, dt):
        step = self.rate * dt
        delta = u - self.value
        if delta > step:
            delta = step
        if delta < -step:
            delta = -step
        self.value = self.value + delta
        out = self.value
        if out != 0.0:
            sign = 1.0 if out > 0.0 else -1.0
            out = sign * (self.dead + (1.0 - self.dead) * abs(out))
        if out > self.high:
            out = self.high
            self.saturated = True
        elif out < self.low:
            out = self.low
            self.saturated = True
        else:
            self.saturated = False
        return out

