import math
DT = 0.005

def gravity_ff(theta_rad, kg):
    return kg * math.cos(theta_rad)

def settle(use_g, kp=0.9, kd=0.05, kg=0.35, target=0.7, steps=3000):
    theta = 0.0
    omega = 0.0
    for _ in range(steps):
        u = kp * (target - theta) - kd * omega
        if use_g:
            u = u + gravity_ff(theta, kg)
        u = min(1.0, max(-1.0, u))
        omega = omega + (6.0 * u - 2.2 * omega - 2.1 * math.cos(theta)) * DT
        theta = theta + omega * DT
    return target - theta

