class Safety:
    def __init__(self, fall=0.6, recover=0.15, hold=1.0):
        self.fall = fall
        self.recover = recover
        self.hold = hold
        self.armed = True
        self.steady = 0.0

    def check(self, angle, rate, dt):
        if self.armed:
            if abs(angle) > self.fall:
                self.armed = False
                self.steady = 0.0
            return self.armed
        if abs(angle) < self.recover and abs(rate) < 0.5:
            self.steady = self.steady + dt
            if self.steady >= self.hold:
                self.armed = True
                self.steady = 0.0
        else:
            self.steady = 0.0
        return self.armed

